// Run against a fresh prototype in an isolated agent-browser session.
(async () => {
 const wait=()=>new Promise(r=>setTimeout(r,180)), check=(v,m)=>{if(!v)throw Error(m)};
 const click=async(label,scope=document)=>{const button=[...scope.querySelectorAll('button,a')].find(e=>e.textContent.trim()===label);check(button,'Missing '+label);button.click();await wait()};
 const fieldInput=(label,scope=document)=>{const field=[...scope.querySelectorAll('.field')].find(e=>e.querySelector('label')?.textContent.replace(' *','').trim()===label);const el=field?.querySelector('input:not([type=hidden]),textarea');check(el,'Missing '+label);return el;};
 const fill=async(label,value,scope=document)=>{const el=fieldInput(label,scope);Object.getOwnPropertyDescriptor(el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 const state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
 location.hash='/chat?channel_id=launch';await wait();
 await click("赞同");
 const count=state().work.length;
 const shell=document.querySelector('.app-shell');
 await click('转为工作');
 check(location.hash.includes('quick_work='),'Conversion did not locate its inline task draft');
 check(document.querySelectorAll('dialog[open]').length===1&&document.querySelector('.app-shell')===shell,'Conversion must open one modal without replacing the shell');
 check(location.hash.split('?')[0]==='#/chat'&&new URLSearchParams(location.hash.split('?')[1]).get('channel_id')==='launch','Conversion left its source channel');
 const draftId=new URLSearchParams(location.hash.split('?')[1]).get('quick_work'), draft=state().drafts[draftId];
 check(draft.source?.messageId && draft.project==='launch' && draft.tenantId===state().activeTenant,'Source/project/tenant not preserved');
 check(state().work.length===count,'Draft prematurely created formal work');
 await fill('想要完成什么','会话讨论后确认的工作');await fill('怎样才算完成','完整保留来源、讨论与固定验收条件');await click('保存任务草稿',document.querySelector('dialog[open]'));
 check(state().drafts[draftId].title==='会话讨论后确认的工作'&&state().work.length===count,'Saving the modal did not retain the draft or prematurely created work');
 document.querySelector('dialog[open] [aria-label="关闭弹窗"]').click();await wait();
 check(!document.querySelector('dialog[open]')&&!new URLSearchParams(location.hash.split('?')[1]).has('quick_work'),'Saved task draft did not close cleanly in its source page');
 location.hash=`/chat?channel_id=${encodeURIComponent(draft.channel)}&work_draft=${encodeURIComponent(draftId)}${draft.threadId?`&thread_id=${encodeURIComponent(draft.threadId)}`:''}`;await wait();
 check(document.body.textContent.includes('会话工作草稿')&&!document.querySelector('dialog[open]'),'Saved draft could not continue in its source conversation');
 const inlineTitle=fieldInput('想要完成什么',document.querySelector('.messages')).value;
 const sourceCard=[...document.querySelectorAll('.message')].find(message=>message.dataset.segment===`message:${draft.source.messageId}`);
 check(sourceCard,'Original source card missing beside the inline draft');
 await click('转为工作',sourceCard);
 const reopened=new URLSearchParams(location.hash.split('?')[1]);
 check(reopened.get('work_draft')===draftId&&reopened.get('quick_work')===draftId,'Same-source conversion did not reuse the mounted inline draft');
 check(document.querySelectorAll('dialog[open]').length===1,'Same draft opened duplicate modals');
 const updatedTitle='弹窗保存的新标题 B', updatedCriteria='弹窗保存的新完成条件 B';
 check(inlineTitle!==updatedTitle,'Regression requires distinct old and new draft values');
 await fill('想要完成什么',updatedTitle,document.querySelector('dialog[open]'));
 await fill('怎样才算完成',updatedCriteria,document.querySelector('dialog[open]'));
 await click('保存任务草稿',document.querySelector('dialog[open]'));
 check(state().drafts[draftId].title===updatedTitle&&state().drafts[draftId].criteria===updatedCriteria,'Modal changes were not saved to the existing draft');
 document.querySelector('dialog[open] [aria-label="关闭弹窗"]').click();await wait();
 check(!document.querySelector('dialog[open]')&&new URLSearchParams(location.hash.split('?')[1]).get('work_draft')===draftId,'Closing the saved modal lost the mounted source draft');
 check(fieldInput('想要完成什么',document.querySelector('.messages')).value===updatedTitle&&fieldInput('怎样才算完成',document.querySelector('.messages')).value===updatedCriteria,'Inline draft retained stale fields after modal save');
 const composer=document.querySelector('textarea[aria-label="消息内容"]');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(composer,'补充：本次先验证可用原型');composer.dispatchEvent(new Event('input',{bubbles:true}));await wait();await click('发送');
 check(state().drafts[draftId].discussion.length===1,'Discussion not linked to draft');
 await click('确认生成工作与计划');
 const work=state().work.find(w=>w.draftId===draftId);
 check(work?.plan===true && work.flow===false && work.project==='launch','Confirmed work/plan or context incorrect');
 check(work.title===updatedTitle&&work.planSnapshot.goal===updatedTitle&&work.planSnapshot.criteria===updatedCriteria,'Inline confirmation overwrote modal changes with stale title or acceptance criteria');
 check(work.source===draft.source.messageId && work.sourceContext.text===draft.source.text,'Immutable source lost');
 check(work.planSnapshot.discussion[0].text==='补充：本次先验证可用原型','Discussion absent from plan');
 check(state().work.length===count+1,'Confirmation created wrong number of work items');
 location.hash=`/chat?channel_id=launch&work_draft=${draftId}`;await wait();check(document.body.textContent.includes('打开生成的工作与计划'),'Confirmed draft history is unavailable');
 return {pass:true,checks:['message to one inline task modal','saved draft resumes source conversation','same-draft modal save updates inline fields and confirmed plan','no premature formal work','source tenant and project retained','discussion linked','single confirmed work and plan','confirmed draft remains accessible']};
})()
